if ($env:CONFIRMATION -cne 'MIGRATE_PRODUCTION_45_TO_47') {
  throw 'The required production confirmation is missing.'
}
$stagingSha = 'c57381b546e920822103b12d8466623ee89733a3'
$run = gh api repos/Rakky88/DragonHaven/actions/runs/34111166461 | ConvertFrom-Json
if ($LASTEXITCODE -ne 0 -or $run.conclusion -ne 'success' -or $run.head_sha -ne $stagingSha) {
  throw 'The exact staging evidence is missing or failed.'
}
git fetch --depth=1 origin $stagingSha
if ($LASTEXITCODE -ne 0) { throw 'Could not resolve the tested staging commit.' }
git diff --exit-code $stagingSha -- supabase/migrations tool/chest_opening_contract.sql tool/item_shop_contract.sql tool/egg_altar_contract.sql
if ($LASTEXITCODE -ne 0) { throw 'The production server content differs from tested staging.' }
foreach ($name in @('SUPABASE_ACCESS_TOKEN', 'SUPABASE_DB_PASSWORD')) {
  if ([string]::IsNullOrWhiteSpace(
      [Environment]::GetEnvironmentVariable($name))) {
    throw "Missing production secret: $name."
  }
}
$expectedRemote = '202609070044'
$expectedPending = @(
  '202609070045', '202609070046', '202609070047')
supabase link --project-ref tnzathhutuwmohmjfrlo `
  --password $env:SUPABASE_DB_PASSWORD
New-Item -ItemType Directory -Path production-migration -Force |
  Out-Null
$migrationResult = ((supabase migration list --linked `
  --output-format json) | Out-String) | ConvertFrom-Json
if ($LASTEXITCODE -ne 0) { throw 'Could not read production migrations.' }
$remoteVersions = @($migrationResult.migrations |
  ForEach-Object { [string]$_.remote } |
  Where-Object { -not [string]::IsNullOrWhiteSpace($_) } |
  Sort-Object)
if ($remoteVersions.Count -eq 0 -or
    $remoteVersions[-1] -ne $expectedRemote) {
  throw 'Production is not exactly at migration 44.'
}
$pendingLocal = @(Get-ChildItem supabase/migrations -File -Filter '*.sql' |
  ForEach-Object {
    if ($_.BaseName -notmatch '^(\d+)_') {
      throw "Invalid migration filename: $($_.Name)."
    }
    $Matches[1]
  } | Where-Object { [long]$_ -gt [long]$expectedRemote } | Sort-Object)
if (@(Compare-Object $expectedPending $pendingLocal).Count -ne 0) {
  throw 'The pending production set is not exactly migrations 45 through 47.'
}
$expectedExisting = @(Get-ChildItem supabase/migrations -File -Filter '*.sql' |
  ForEach-Object { $_.BaseName.Split('_')[0] } |
  Where-Object { [long]$_ -le [long]$expectedRemote } | Sort-Object)
if (@(Compare-Object $expectedExisting $remoteVersions).Count -ne 0) {
  throw 'Existing production migrations differ from the exact tested baseline.'
}
$state = Invoke-RestMethod -Method Post `
  -Uri 'https://api.supabase.com/v1/projects/tnzathhutuwmohmjfrlo/database/query' `
  -Headers @{ Authorization = "Bearer $env:SUPABASE_ACCESS_TOKEN" } `
  -ContentType 'application/json' `
  -Body (ConvertTo-Json @{ query = "select (select mutations_enabled from private.economy_contract) as enabled, (select count(*) from public.player_economy_authority where authority_mode <> 'legacy_client') as nonlegacy;"; read_only = $true } -Compress)
if (@($state).Count -ne 1 -or $state[0].enabled -ne $false -or $state[0].nonlegacy -ne 0) {
  throw 'Economy must remain disabled and every keeper in legacy compatibility mode.'
}
$state | ConvertTo-Json | Set-Content production-migration/authority-before.json
./tool/public_server_health_check.ps1 `
  -Environment production `
  -OutputPath production-migration/health-before.json
supabase db lint --linked --level error --fail-on error `
  --output-format json | Tee-Object production-migration/lint-before.json
if ($LASTEXITCODE -ne 0) { throw 'Pre-migration lint failed.' }
supabase db push --linked --include-all --dry-run |
  Tee-Object production-migration/dry-run.txt
if ($LASTEXITCODE -ne 0) { throw 'Production dry run failed.' }
foreach ($contractName in @('chest_opening', 'item_shop', 'egg_altar')) {
  $sql = "begin;`n"
  foreach ($version in @('202609070045', '202609070046', '202609070047')) {
    $file = Get-ChildItem supabase/migrations -File -Filter "$($version)_*.sql"
    if (@($file).Count -ne 1) { throw 'The migration set is ambiguous.' }
    $sql += (Get-Content -LiteralPath $file.FullName -Raw) + "`n"
  }
  $contract = Get-Content -LiteralPath "tool/$($contractName)_contract.sql" -Raw
  $sql += [regex]::Replace($contract, '(?m)^begin;\r?\n', '', 1)
  $response = Invoke-RestMethod -Method Post `
    -Uri 'https://api.supabase.com/v1/projects/tnzathhutuwmohmjfrlo/database/query' `
    -Headers @{ Authorization = "Bearer $env:SUPABASE_ACCESS_TOKEN" } `
    -ContentType 'application/json' `
    -Body (ConvertTo-Json @{ query = $sql; read_only = $false } -Compress)
  if (@($response).Count -ne 1 -or $response[0]."$($contractName)_contract_passed" -ne $true) {
    throw 'Rolled-back production rehearsal failed; migrations will not be applied.'
  }
}
'PASS: all three contracts and migrations rolled back before applying.' |
  Set-Content production-migration/rehearsal.txt
supabase db push --linked --include-all --yes |
  Tee-Object production-migration/apply.txt
if ($LASTEXITCODE -ne 0) { throw 'Production migration apply failed.' }
foreach ($contractName in @('chest_opening', 'item_shop', 'egg_altar')) {
  $contract = Get-Content -LiteralPath "tool/$($contractName)_contract.sql" -Raw
  $response = Invoke-RestMethod -Method Post `
    -Uri 'https://api.supabase.com/v1/projects/tnzathhutuwmohmjfrlo/database/query' `
    -Headers @{ Authorization = "Bearer $env:SUPABASE_ACCESS_TOKEN" } `
    -ContentType 'application/json' `
    -Body (ConvertTo-Json @{ query = $contract; read_only = $false } -Compress)
  if (@($response).Count -ne 1 -or $response[0]."$($contractName)_contract_passed" -ne $true) {
    throw "The applied $contractName contract failed."
  }
}
'PASS: chest opening, restore guards, item shop and existing Altar; all test mutations rolled back.' |
  Set-Content production-migration/contract.txt
$state = Invoke-RestMethod -Method Post `
  -Uri 'https://api.supabase.com/v1/projects/tnzathhutuwmohmjfrlo/database/query' `
  -Headers @{ Authorization = "Bearer $env:SUPABASE_ACCESS_TOKEN" } `
  -ContentType 'application/json' `
  -Body (ConvertTo-Json @{ query = "select (select mutations_enabled from private.economy_contract) as enabled, (select count(*) from public.player_economy_authority where authority_mode <> 'legacy_client') as nonlegacy;"; read_only = $true } -Compress)
if (@($state).Count -ne 1 -or $state[0].enabled -ne $false -or $state[0].nonlegacy -ne 0) {
  throw 'Economy must remain disabled and every keeper in legacy compatibility mode.'
}
$state | ConvertTo-Json | Set-Content production-migration/authority-after.json
./tool/release_server_preflight.ps1 |
  Tee-Object production-migration/preflight-after.txt
supabase db lint --linked --level error --fail-on error `
  --output-format json | Tee-Object production-migration/lint-after.json
if ($LASTEXITCODE -ne 0) { throw 'Post-migration lint failed.' }
./tool/public_server_health_check.ps1 `
  -Environment production `
  -OutputPath production-migration/health-after.json
@(
  'DragonHaven production migration evidence'
  "Commit: $env:GITHUB_SHA"
  'Previous migration: 202609070044'
  'Applied migrations: 202609070045 through 202609070047'
  'Economy authority remains in disabled legacy compatibility mode.'
  'Chest opening and item shop are dormant; existing Altar behavior is preserved.'
  'Migration parity, database lint, Auth and application health: passed'
  'No credentials or player data are included in this artifact.'
) | Set-Content production-migration/verification.txt -Encoding utf8
